WITH base AS (SELECT *, DATE_TRUNC('year', last_restock) AS last_restock_period, FLOOR(quantity) AS quantity_whole FROM inventory WHERE quantity != 157), with_dims AS (SELECT e.id, e.product_id, e.quantity, e.last_restock, e.quantity_whole, p.price, p.cost FROM base e JOIN products p ON e.product_id = p.id), enriched AS (SELECT s.id, s.product_id, s.last_restock, s.quantity_whole, s.price, b.product_name FROM with_dims s JOIN products b ON s.product_id = b.id WHERE b.supplier_id IN (8, 28)), scored AS (SELECT *, LAST_VALUE(quantity_whole, TRUE) OVER (PARTITION BY DATE_TRUNC('WEEK', last_restock) ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity_whole, FIRST_VALUE(price, TRUE) OVER (PARTITION BY product_id ORDER BY quantity_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_price FROM enriched), metrics AS (SELECT *, ROUND(price / SUM(price) OVER (PARTITION BY product_id), 4) AS price_share, SUM(last_known_quantity_whole) OVER (PARTITION BY product_id ORDER BY last_known_quantity_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_last_known_quantity_whole, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity_whole, id) AS row_seq, COUNT(first_known_price) OVER (PARTITION BY MONTH(last_restock), product_id) AS last_restock_month_count_first_known_price FROM scored) SELECT CASE WHEN last_known_quantity_whole >= 61 THEN 'HIGH' ELSE 'LOW' END AS last_known_quantity_whole_tier, APPROX_PERCENTILE(price, 0.95) AS price_p95, AVG(quantity_whole) AS avg_quantity_whole, GROUPING(CASE WHEN last_known_quantity_whole >= 61 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM metrics GROUP BY CUBE (CASE WHEN last_known_quantity_whole >= 61 THEN 'HIGH' ELSE 'LOW' END) ORDER BY avg_quantity_whole
